78: fn active_snapshot<T: Project>(values: &[T]) -> Snapshot {
79:     if values.len() > CAP {
80:         return Snapshot::invalid();
81:     }
82:     let mut result = Snapshot { values: [0; CAP], len: values.len(), valid: true };
83:     let mut i = 0;
84:     while i < result.len {
85:         result.values[i] = values[i].value();
86:         i += 1;
87:     }
88:     result
89: }
