91: fn active_post<T: Project>(before: Snapshot, values: &[T]) -> bool {
92:     if !before.valid || before.len > CAP || values.len() > CAP || before.len != values.len() {
93:         return false;
94:     }
95:     let mut i = 1;
96:     while i < before.len {
97:         if values[i].value() < values[i - 1].value() {
98:             return false;
99:         }
100:         i += 1;
101:     }
102:     // Checking each input value (duplicates may repeat a check) covers the whole
103:     // multiset: equal input/output lengths leave no room for a novel output value.
104:     i = 0;
105:     while i < before.len {
106:         let query = before.values[i];
107:         let mut old_count: usize = 0;
108:         let mut new_count: usize = 0;
109:         let mut j = 0;
110:         while j < before.len {
111:             if before.values[j] == query { old_count += 1; }
112:             if values[j].value() == query { new_count += 1; }
113:             j += 1;
114:         }
115:         if old_count != new_count {
116:             return false;
117:         }
118:         i += 1;
119:     }
120:     true

